package redirector

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

const (
	MaxFailures    = 5
	ResetTimeout   = 30 * time.Second
	HMACSecretKey  = "production-secret-key-2024"
)

type CircuitState int

const (
	StateClosed CircuitState = iota
	StateOpen
	StateHalfOpen
)

type CircuitBreaker struct {
	mu           sync.Mutex
	state        CircuitState
	failures     int
	lastFailure  time.Time
	allowedHosts map[string]bool
}

func NewCircuitBreaker(hosts []string) *CircuitBreaker {
	allowed := make(map[string]bool)
	for _, h := range hosts {
		allowed[h] = true
	}
	return &CircuitBreaker{
		state:        StateClosed,
		allowedHosts: allowed,
	}
}

func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.lastFailure = time.Now()
	if cb.failures >= MaxFailures {
		cb.state = StateOpen
	}
}

func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.state = StateClosed
}

func (cb *CircuitBreaker) CanExecute() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	switch cb.state {
	case StateClosed:
		return true
	case StateOpen:
		if time.Since(cb.lastFailure) > ResetTimeout {
			cb.state = StateHalfOpen
			return true
		}
		return false
	case StateHalfOpen:
		return true
	}
	return false
}

func generateHMAC(target string) string {
	mac := hmac.New(sha256.New, []byte(HMACSecretKey))
	mac.Write([]byte(target))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyHMAC(target, signature string) bool {
	expected := generateHMAC(target)
	return hmac.Equal([]byte(expected), []byte(signature))
}

func (cb *CircuitBreaker) validateRedirectTarget(rawTarget string) (string, error) {
	if !cb.CanExecute() {
		return "", fmt.Errorf("circuit breaker open: too many validation failures")
	}

	parsed, err := url.Parse(rawTarget)
	if err != nil {
		cb.RecordFailure()
		return "", fmt.Errorf("invalid URL: %w", err)
	}

	normalizedHost := strings.ToLower(parsed.Hostname())

	if parsed.Scheme != "" && parsed.Scheme != "https" {
		cb.RecordFailure()
		return "", fmt.Errorf("scheme not allowed: %s", parsed.Scheme)
	}

	if normalizedHost != "" && !cb.allowedHosts[normalizedHost] {
		cb.RecordFailure()
		return "", fmt.Errorf("host not allowed: %s", normalizedHost)
	}

	cb.RecordSuccess()
	return rawTarget, nil
}

func (cb *CircuitBreaker) HandleRedirect(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("url")
	signature := r.URL.Query().Get("sig")

	if target == "" {
		http.Error(w, "missing url parameter", http.StatusBadRequest)
		return
	}

	if signature == "" {
		http.Error(w, "missing signature", http.StatusBadRequest)
		return
	}

	if !verifyHMAC(target, signature) {
		http.Error(w, "invalid signature", http.StatusForbidden)
		return
	}

	validated, err := cb.validateRedirectTarget(target)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}

	http.Redirect(w, r, validated, http.StatusFound)
}

func (cb *CircuitBreaker) HandleSignedRedirectCreation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	target := r.FormValue("target")
	if target == "" {
		http.Error(w, "missing target", http.StatusBadRequest)
		return
	}

	_, err := cb.validateRedirectTarget(target)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	sig := generateHMAC(target)
	redirectURL := fmt.Sprintf("/redirect?url=%s&sig=%s", url.QueryEscape(target), sig)
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"redirect_url": "%s"}`, redirectURL)
}
